    rdfs:comment "The EDIFACT interchange envelope containing one or more messages." .

:Message a owl:Class ;
    rdfs:label "Message" ;
    rdfs:comment "An EDIFACT message, such as INVOIC, within an interchange envelope." .

:Invoice a owl:Class ;
    rdfs:subClassOf :Message ;
    rdfs:label "Invoice" ;
    rdfs:comment "A business invoice message compliant with EDIFACT D96A INVOIC." .

:Segment a owl:Class ;
    rdfs:label "Segment" ;
    rdfs:comment "A generic segment within an EDIFACT message." .

:HeaderSection a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "Header Section" ;
    rdfs:comment "The header section of the invoice, containing general document information." .

:DetailSection a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "Detail Section" ;
    rdfs:comment "The detail section of the invoice, containing line items." .

:SummarySection a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "Summary Section" ;
    rdfs:comment "The summary section of the invoice, containing totals and controls." .

:CompositeDataElement a owl:Class ;
    rdfs:label "Composite Data Element" ;
    rdfs:comment "A composite data element within a segment." .

:SimpleDataElement a owl:Class ;
    rdfs:label "Simple Data Element" ;
    rdfs:comment "A simple data element within a composite or segment." .

:Organization a owl:Class ;
    rdfs:label "Organization" ;
    rdfs:comment "An organization involved in the invoice process." .

:AgentRole a owl:Class ;
    rdfs:label "Agent Role" ;
    rdfs:comment "A role played by an organization in the invoice, e.g., buyer, seller, delivery party." .

:Address a owl:Class ;
    rdfs:label "Address" ;
    rdfs:comment "A postal or physical address associated with an organization." .

:GlobalLocationNumber a owl:Class ;
    rdfs:subClassOf :Identifier ;
    rdfs:label "Global Location Number" ;
    rdfs:comment "A GLN identifier for organizations or locations." .

:Item a owl:Class ;
    rdfs:label "Item" ;
    rdfs:comment "A product or service described in the invoice." .

:Price a owl:Class ;
    rdfs:label "Price" ;
    rdfs:comment "A price associated with an invoiced item." .

:Quantity a owl:Class ;
    rdfs:label "Quantity" ;
    rdfs:comment "A quantity associated with an invoiced item." .

:Tax a owl:Class ;
    rdfs:label "Tax" ;
    rdfs:comment "Tax information relevant to the invoice or line item." .

:ReferenceNumber a owl:Class ;
    rdfs:subClassOf :Identifier ;
    rdfs:label "Reference Number" ;
    rdfs:comment "A reference number, such as invoice number or order number." .

