    rdfs:comment "BGM segment for document identification, type code, and function code." .

:Reference a owl:Class ;
    rdfs:subClassOf :HeaderSection ;
    rdfs:label "Reference" ;
    rdfs:comment "RFF segment for references such as invoice number, order number, etc." .

:LineItem a owl:Class ;
    rdfs:subClassOf :DetailSection ;
    rdfs:label "Line Item" ;
    rdfs:comment "LIN segment for individual line items." .

