    rdfs:label "Segment Group 7" ;
    rdfs:comment "SG7 group for line item details." .

:SegmentGroup25 a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "Segment Group 25" ;
    rdfs:comment "SG25 group for monetary amounts and taxes in the summary." .

:SegmentGroup34 a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "Segment Group 34" ;
    rdfs:comment "SG34 group for tax breakdowns in the summary." .

:MonetaryAmountSegment a owl:Class ;
    rdfs:subClassOf :SummarySection ;
    rdfs:label "Monetary Amount Segment" ;
    rdfs:comment "MOA segment for invoice totals and amounts." .

:TaxSegment a owl:Class ;
    rdfs:subClassOf :SummarySection ;
    rdfs:label "Tax Segment" ;
    rdfs:comment "TAX segment for tax details in the summary." .

:QuantitySegment a owl:Class ;
    rdfs:subClassOf :DetailSection ;
    rdfs:label "Quantity Segment" ;
    rdfs:comment "QTY segment for quantities at line and document level." .

:DateTimeSegment a owl:Class ;
    rdfs:subClassOf :HeaderSection ;
    rdfs:label "Date/Time Segment" ;
    rdfs:comment "DTM segment for date/time information beyond core document dates." .

:NameAndAddressSegment a owl:Class ;
    rdfs:subClassOf :HeaderSection ;
    rdfs:label "Name and Address Segment" ;
    rdfs:comment "NAD segment for party identification and address detail." .

:SegmentGroup1 a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "Segment Group 1" ;
    rdfs:comment "SG1 group for references at the header level." .

:SegmentGroup27 a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "Segment Group 27" ;
    rdfs:comment "SG27 group for allowances and charges in the summary." .

