    rdfs:subClassOf :Identifier .

:ReferenceNumber rdf:type owl:Class ;
    rdfs:label "Reference Number" ;
    rdfs:comment "Reference number for the invoice or line item." ;
    rdfs:subClassOf :Identifier .

:Date rdf:type owl:Class ;
    rdfs:label "Date" ;
    rdfs:comment "A date value (not a segment, but used in segments)." .

:RoleAssignment rdf:type owl:Class ;
    rdfs:label "Role Assignment" ;
    rdfs:comment "Pivot class linking organizations to their roles within an invoice." .

