@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .
@prefix owl: <http://www.w3.org/2002/07/owl#> .
@prefix : <http://www.example.org/ontology#> .

:EDIFACT_INVOIC_Ontology rdf:type owl:Ontology ;
    rdfs:label "EDIFACT INVOIC Ontology" ;
    rdfs:comment "A deep and profoundly structured ontology for UN/EDIFACT INVOIC messages, covering D96A/EANCOM, EN 16931-1, and P2P-O alignment." .

# Core Classes

:InterchangeEnvelope rdf:type owl:Class ;
    rdfs:label "Interchange Envelope" ;
    rdfs:comment "The envelope containing one or more EDIFACT messages." .

:Message rdf:type owl:Class ;
    rdfs:label "Message" ;
    rdfs:comment "A generic EDIFACT message, possibly of type INVOIC." .

:INVOICMessage rdf:type owl:Class ;
    rdfs:label "INVOIC Message" ;
    rdfs:comment "A specific EDIFACT INVOIC message for global trade transactions." ;
    rdfs:subClassOf :Message ;
    owl:equivalentClass [ rdf:type owl:Restriction ; owl:onProperty :representsInvoice ; owl:allValuesFrom :Invoice ] .

:Segment rdf:type owl:Class ;
    rdfs:label "Segment" ;
    rdfs:comment "A structural unit of an EDIFACT message." .

:BGM_Segment rdf:type owl:Class ;
    rdfs:label "BGM Segment" ;
    rdfs:comment "Beginning of Message segment, identifies the document." ;
    rdfs:subClassOf :Segment .

:NAD_Segment rdf:type owl:Class ;
    rdfs:label "NAD Segment" ;
    rdfs:comment "Name and Address segment, provides organization and participant details." ;
    rdfs:subClassOf :Segment .

:DTM_Segment rdf:type owl:Class ;
    rdfs:label "DTM Segment" ;
    rdfs:comment "Date/Time/Period segment, with qualifier-based subclasses for document, delivery, and payment dates." ;
    rdfs:subClassOf :Segment .

:DocumentDate rdf:type owl:Class ;
    rdfs:label "Document Date" ;
    rdfs:comment "DTM segment for the invoice document date (DTM+137)." ;
    rdfs:subClassOf :DTM_Segment .

:DeliveryDate rdf:type owl:Class ;
    rdfs:label "Delivery Date" ;
    rdfs:comment "DTM segment for delivery date." ;
    rdfs:subClassOf :DTM_Segment .

:PaymentDueDate rdf:type owl:Class ;
    rdfs:label "Payment Due Date" ;
    rdfs:comment "DTM segment for payment due date." ;
    rdfs:subClassOf :DTM_Segment .

:RFF_Segment rdf:type owl:Class ;
    rdfs:label "RFF Segment" ;
    rdfs:comment "Reference segment, contains document reference numbers." ;
    rdfs:subClassOf :Segment .

:MonetaryAmountSegment rdf:type owl:Class ;
    rdfs:label "Monetary Amount Segment" ;
    rdfs:comment "Segment for monetary totals, net, gross, and tax amounts." ;
    rdfs:subClassOf :Segment .

:TaxCalculationSegment rdf:type owl:Class ;
    rdfs:label "Tax Calculation Segment" ;
    rdfs:comment "Segment for tax calculation details." ;
    rdfs:subClassOf :Segment .

:DeliveryTermsSegment rdf:type owl:Class ;
    rdfs:label "Delivery Terms Segment" ;
    rdfs:comment "Segment for delivery terms and conditions." ;
    rdfs:subClassOf :Segment .

:PaymentInstructionsSegment rdf:type owl:Class ;
    rdfs:label "Payment Instructions Segment" ;
    rdfs:comment "Segment for payment instructions." ;
    rdfs:subClassOf :Segment .

:CompositeDataElement rdf:type owl:Class ;
    rdfs:label "Composite Data Element" ;
    rdfs:comment "A composite data element in a segment." ;
    rdfs:subClassOf :Segment .

:SimpleDataElement rdf:type owl:Class ;
    rdfs:label "Simple Data Element" ;
    rdfs:comment "A simple data element in a composite element." ;
    rdfs:subClassOf :CompositeDataElement .

:Invoice rdf:type owl:Class ;
    rdfs:label "Invoice" ;
    rdfs:comment "The invoice business document represented in the INVOIC message." ;
    owl:Restriction [ owl:onProperty :hasRoleAssignment ; owl:someValuesFrom :RoleAssignment ] ;
    owl:Restriction [ owl:onProperty :hasLineItem ; owl:someValuesFrom :LineItem ] ;
    owl:Restriction [ owl:onProperty :hasDTMSegment ; owl:someValuesFrom :DTM_Segment ] ;
    owl:Restriction [ owl:onProperty :hasRFFSegment ; owl:someValuesFrom :RFF_Segment ] ;
    owl:Restriction [ owl:onProperty :hasMonetaryAmountSegment ; owl:someValuesFrom :MonetaryAmountSegment ] ;
    owl:Restriction [ owl:onProperty :hasTaxCalculationSegment ; owl:someValuesFrom :TaxCalculationSegment ] ;
    owl:Restriction [ owl:onProperty :hasDeliveryTermsSegment ; owl:someValuesFrom :DeliveryTermsSegment ] ;
    owl:Restriction [ owl:onProperty :hasPaymentInstructionsSegment ; owl:someValuesFrom :PaymentInstructionsSegment ] .

:Organization rdf:type owl:Class ;
    rdfs:label "Organization" ;
    rdfs:comment "An entity involved in the invoice, such as Buyer, Supplier, or Delivery Party." ;
    owl:Restriction [ owl:onProperty :hasAddress ; owl:someValuesFrom :Address ] .

:AgentRole rdf:type owl:Class ;
    rdfs:label "Agent Role" ;
    rdfs:comment "Role played by an organization in a transaction (e.g., Buyer, Supplier, Delivery Party)." .

:Address rdf:type owl:Class ;
    rdfs:label "Address" ;
    rdfs:comment "Physical or legal address of an organization." .

:Item rdf:type owl:Class ;
    rdfs:label "Item" ;
    rdfs:comment "A product or service sold in the invoice." .

:Price rdf:type owl:Class ;
    rdfs:label "Price" ;
    rdfs:comment "The price of an item in a line item." .

:LineItem rdf:type owl:Class ;
    rdfs:label "Line Item" ;
    rdfs:comment "An individual line item in the invoice, with item, price, and quantity." ;
    owl:Restriction [ owl:onProperty :describesItem ; owl:allValuesFrom :Item ] .

:InvoiceHeader rdf:type owl:Class ;
    rdfs:label "Invoice Header" ;
    rdfs:comment "Header section of the invoice, containing document dates and reference numbers." ;
    rdfs:subClassOf :Segment .

:InvoiceDetail rdf:type owl:Class ;
    rdfs:label "Invoice Detail" ;
    rdfs:comment "Detail section of the invoice, listing line items." ;
    rdfs:subClassOf :Segment .

:InvoiceSummary rdf:type owl:Class ;
    rdfs:label "Invoice Summary" ;
    rdfs:comment "Summary section of the invoice, providing total tax and invoice amounts." ;
    rdfs:subClassOf :Segment .

:Tax rdf:type owl:Class ;
    rdfs:label "Tax" ;
    rdfs:comment "Tax applied to the invoice or line item." .

:BusinessProcess rdf:type owl:Class ;
    rdfs:label "Business Process" ;
    rdfs:comment "The business process to which the invoice is assigned." .

:Identifier rdf:type owl:Class ;
    rdfs:label "Identifier" ;
    rdfs:comment "A generic identifier used in the invoice (e.g., reference number, GLN)." .

:GLN_Identifier rdf:type owl:Class ;
    rdfs:label "GLN Identifier" ;
    rdfs:comment "Global Location Number identifier for organizations." ;
    rdfs:subClassOf :Identifier .

:ReferenceNumber rdf:type owl:Class ;
    rdfs:label "Reference Number" ;
    rdfs:comment "Reference number for the invoice or line item." ;
    rdfs:subClassOf :Identifier .

:Date rdf:type owl:Class ;
    rdfs:label "Date" ;
    rdfs:comment "A date value (not a segment, but used in segments)." .

:RoleAssignment rdf:type owl:Class ;
    rdfs:label "Role Assignment" ;
    rdfs:comment "Pivot class linking organizations to their roles within an invoice." .

# Properties

:containsMessage rdf:type owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:label "contains message" ;
    rdfs:comment "InterchangeEnvelope contains one or more Messages." ;
    rdfs:domain :InterchangeEnvelope ;
    rdfs:range :Message .

:hasSegment rdf:type owl:ObjectProperty , owl:TransitiveProperty ;
    rdfs:label "has segment" ;
    rdfs:comment "Message has one or more Segments." ;
    rdfs:domain :Message ;
    rdfs:range :Segment .

:hasCompositeElement rdf:type owl:ObjectProperty ;
    rdfs:label "has composite element" ;
    rdfs:comment "Segment contains composite data elements." ;
    rdfs:domain :Segment ;
    rdfs:range :CompositeDataElement .

:hasSimpleElement rdf:type owl:ObjectProperty ;
    rdfs:label "has simple element" ;
    rdfs:comment "Composite data element contains simple data elements." ;
    rdfs:domain :CompositeDataElement ;
    rdfs:range :SimpleDataElement .

:representsInvoice rdf:type owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:label "represents invoice" ;
    rdfs:comment "INVOICMessage represents a specific Invoice." ;
    rdfs:domain :INVOICMessage ;
    rdfs:range :Invoice .

:hasRoleAssignment rdf:type owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:label "has role assignment" ;
    rdfs:comment "Invoice has one or more RoleAssignments linking organizations to their roles." ;
    rdfs:domain :Invoice ;
    rdfs:range :RoleAssignment .

:assignsRole rdf:type owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:label "assigns role" ;
    rdfs:comment "RoleAssignment assigns a specific AgentRole." ;
    rdfs:domain :RoleAssignment ;
    rdfs:range :AgentRole .

:involvesOrganization rdf:type owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:label "involves organization" ;
    rdfs:comment "RoleAssignment involves a specific Organization." ;
    rdfs:domain :RoleAssignment ;
    rdfs:range :Organization .

:hasAddress rdf:type owl:ObjectProperty ;
    rdfs:label "has address" ;
    rdfs:comment "Organization has one or more Addresses." ;
    rdfs:domain :Organization ;
    rdfs:range :Address .

:hasGLN rdf:type owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:label "has GLN" ;
    rdfs:comment "Organization has a Global Location Number identifier." ;
    rdfs:domain :Organization ;
    rdfs:range :GLN_Identifier .

:hasReferenceNumber rdf:type owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:label "has reference number" ;
    rdfs:comment "Invoice has a reference number." ;
    rdfs:domain :Invoice ;
    rdfs:range xsd:string .

:hasDate rdf:type owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:label "has date" ;
    rdfs:comment "Invoice has a date value." ;
    rdfs:domain :Invoice ;
    rdfs:range xsd:string .

:hasLineItem rdf:type owl:ObjectProperty ;
    rdfs:label "has line item" ;
    rdfs:comment "Invoice has one or more LineItems." ;
    rdfs:domain :Invoice ;
    rdfs:range :LineItem .

:describesItem rdf:type owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:label "describes item" ;
    rdfs:comment "LineItem describes a specific Item." ;
    rdfs:domain :LineItem ;
    rdfs:range :Item .

:hasQuantity rdf:type owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:label "has quantity" ;
    rdfs:comment "LineItem has a quantity value." ;
    rdfs:domain :LineItem ;
    rdfs:range xsd:decimal .

:hasNetPrice rdf:type owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:label "has net price" ;
    rdfs:comment "LineItem has a net price value." ;
    rdfs:domain :LineItem ;
    rdfs:range xsd:decimal .

:hasPrice rdf:type owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:label "has price" ;
    rdfs:comment "LineItem has a Price object." ;
    rdfs:domain :LineItem ;
    rdfs:range :Price .

:hasTax rdf:type owl:ObjectProperty ;
    rdfs:label "has tax" ;
    rdfs:comment "Invoice has a Tax object." ;
    rdfs:domain :Invoice ;
    rdfs:range :Tax .

:hasInvoiceAmount rdf:type owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:label "has invoice amount" ;
    rdfs:comment "Invoice has a total amount value." ;
    rdfs:domain :Invoice ;
    rdfs:range xsd:decimal .

:assignedToProcess rdf:type owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:label "assigned to process" ;
    rdfs:comment "Invoice is assigned to a business process." ;
    rdfs:domain :Invoice ;
    rdfs:range :BusinessProcess .

:hasMandatoryIdentifier rdf:type owl:ObjectProperty ;
    rdfs:label "has mandatory identifier" ;
    rdfs:comment "Invoice has mandatory identifiers (e.g., GLN, reference number)." ;
    rdfs:domain :Invoice ;
    rdfs:range :Identifier .

:hasSummary rdf:type owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:label "has summary" ;
    rdfs:comment "Invoice has a summary section." ;
    rdfs:domain :Invoice ;
    rdfs:range :InvoiceSummary .

:hasDTMSegment rdf:type owl:ObjectProperty ;
    rdfs:label "has DTM segment" ;
    rdfs:comment "Invoice has one or more DTM segments (dates)." ;
    rdfs:domain :Invoice ;
    rdfs:range :DTM_Segment .

:hasRFFSegment rdf:type owl:ObjectProperty ;
    rdfs:label "has RFF segment" ;
    rdfs:comment "Invoice has one or more RFF segments (references)." ;
    rdfs:domain :Invoice ;
    rdfs:range :RFF_Segment .

:hasMonetaryAmountSegment rdf:type owl:ObjectProperty ;
    rdfs:label "has monetary amount segment" ;
    rdfs:comment "Invoice has one or more monetary amount segments (totals, net, gross, tax)." ;
    rdfs:domain :Invoice ;
    rdfs:range :MonetaryAmountSegment .

:hasTaxCalculationSegment rdf:type owl:ObjectProperty ;
    rdfs:label "has tax calculation segment" ;
    rdfs:comment "Invoice has one or more tax calculation segments." ;
    rdfs:domain :Invoice ;
    rdfs:range :TaxCalculationSegment .

:hasDeliveryTermsSegment rdf:type owl:ObjectProperty ;
    rdfs:label "has delivery terms segment" ;
    rdfs:comment "Invoice has one or more delivery terms segments." ;
    rdfs:domain :Invoice ;
    rdfs:range :DeliveryTermsSegment .

:hasPaymentInstructionsSegment rdf:type owl:ObjectProperty ;
    rdfs:label "has payment instructions segment" ;
    rdfs:comment "Invoice has one or more payment instructions segments." ;
    rdfs:domain :Invoice ;
    rdfs:range :PaymentInstructionsSegment .

# Disjointness and DisjointUnion

:InterchangeEnvelope owl:disjointWith :Message .
:Message owl:disjointWith :Segment .
:Segment owl:disjointWith :CompositeDataElement .
:CompositeDataElement owl:disjointWith :SimpleDataElement .
:Organization owl:disjointWith :Address .
:Invoice owl:disjointWith :Organization .
:Item owl:disjointWith :Price .

:Segment owl:disjointUnionOf ( :BGM_Segment :NAD_Segment :DTM_Segment :MonetaryAmountSegment :TaxCalculationSegment :DeliveryTermsSegment :PaymentInstructionsSegment :InvoiceHeader :InvoiceDetail :InvoiceSummary ) .

