:Item owl:disjointWith :Price .

:Segment owl:disjointUnionOf ( :BGM_Segment :NAD_Segment :DTM_Segment :MonetaryAmountSegment :TaxCalculationSegment :DeliveryTermsSegment :PaymentInstructionsSegment :InvoiceHeader :InvoiceDetail :InvoiceSummary ) .

