@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .
@prefix owl: <http://www.w3.org/2002/07/owl#> .
@prefix : <http://www.example.org/ontology#> .

<http://www.example.org/ontology#EDIFACTInvoiceOntology> a owl:Ontology ;
    rdfs:label "EDIFACT Invoice Ontology" ;
    rdfs:comment "A deeply structured ontology for UN/EDIFACT invoice messages, reflecting D96A, EN 16931-1, and P2P-O alignment." .

#################################################################
# Classes
#################################################################

:InterchangeEnvelope a owl:Class ;
    rdfs:label "Interchange Envelope" ;
    rdfs:comment "The outermost envelope for UN/EDIFACT transmissions, containing one or more messages." .

:Message a owl:Class ;
    rdfs:label "Message" ;
    rdfs:comment "A business message within an interchange envelope." .

:InvoiceMessage a owl:Class ;
    rdfs:label "Invoice Message" ;
    rdfs:comment "An EDIFACT INVOIC message representing a global trade invoice." ;
    rdfs:subClassOf :Message .

:Segment a owl:Class ;
    rdfs:label "Segment" ;
    rdfs:comment "A segment in an EDIFACT message, such as BGM or NAD." .

:BGMSegment a owl:Class ;
    rdfs:label "BGM Segment" ;
    rdfs:comment "Beginning of Message (BGM) segment for document identification." ;
    rdfs:subClassOf :Segment .

:NADSegment a owl:Class ;
    rdfs:label "NAD Segment" ;
    rdfs:comment "Name and Address (NAD) segment for participant details." ;
    rdfs:subClassOf :Segment .

:CompositeDataElement a owl:Class ;
    rdfs:label "Composite Data Element" ;
    rdfs:comment "A composite data element grouping in a segment." .

:SimpleDataElement a owl:Class ;
    rdfs:label "Simple Data Element" ;
    rdfs:comment "The simplest data unit in an EDIFACT segment." .

:InvoiceHeader a owl:Class ;
    rdfs:label "Invoice Header" ;
    rdfs:comment "Header section of an invoice message, containing document dates and reference numbers." ;
    rdfs:subClassOf :CompositeDataElement .

:InvoiceDetail a owl:Class ;
    rdfs:label "Invoice Detail" ;
    rdfs:comment "Detail section listing line items in the invoice." ;
    rdfs:subClassOf :CompositeDataElement .

:InvoiceSummary a owl:Class ;
    rdfs:label "Invoice Summary" ;
    rdfs:comment "Summary section providing total tax and invoice amounts." ;
    rdfs:subClassOf :CompositeDataElement .

:Organization a owl:Class ;
    rdfs:label "Organization" ;
    rdfs:comment "A business or legal entity involved in the invoice process." .

:AgentRole a owl:Class ;
    rdfs:label "Agent Role" ;
    rdfs:comment "A role played by an organization in a transaction (buyer, supplier, delivery party, etc.)." .

:OrganizationRoleAssignment a owl:Class ;
    rdfs:label "Organization Role Assignment" ;
    rdfs:comment "Pivot class for reifying the assignment of a role to an organization within a specific invoice context." .

:Address a owl:Class ;
    rdfs:label "Address" ;
    rdfs:comment "A postal address associated with an organization." .

:Item a owl:Class ;
    rdfs:label "Item" ;
    rdfs:comment "A product or service being invoiced." .

:LineItem a owl:Class ;
    rdfs:label "Line Item" ;
    rdfs:comment "A single item entry in the invoice detail section." ;
    rdfs:subClassOf :CompositeDataElement .

:Price a owl:Class ;
    rdfs:label "Price" ;
    rdfs:comment "A price amount associated with an item or invoice." ;
    rdfs:subClassOf :CompositeDataElement .

:Tax a owl:Class ;
    rdfs:label "Tax" ;
    rdfs:comment "Tax information relevant to the invoice." ;
    rdfs:subClassOf :CompositeDataElement .

:ReferenceNumber a owl:Class ;
    rdfs:label "Reference Number" ;
    rdfs:comment "A reference number associated with the invoice or its components." .

:BusinessProcess a owl:Class ;
    rdfs:label "Business Process" ;
    rdfs:comment "A business process to which the invoice can be assigned." .

:GlobalLocationNumber a owl:Class ;
    rdfs:label "Global Location Number" ;
    rdfs:comment "A class representing a global location number identifier." .

:Identifier a owl:Class ;
    rdfs:label "Identifier" ;
    rdfs:comment "A generic identifier for elements within the invoice." ;
    rdfs:subClassOf :SimpleDataElement .

#################################################################
# Disjointness
#################################################################

:Organization owl:disjointWith :Item .
:InvoiceHeader owl:disjointWith :InvoiceDetail, :InvoiceSummary .
:InvoiceDetail owl:disjointWith :InvoiceSummary .
:Address owl:disjointWith :Price .
:AgentRole owl:disjointWith :Address .

#################################################################
# Object Properties
#################################################################

:containsMessage a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:label "contains message" ;
    rdfs:comment "Relates an interchange envelope to the message(s) it contains." ;
    rdfs:domain :InterchangeEnvelope ;
    rdfs:range :Message ;
    owl:inverseOf :isContainedInEnvelope .

:isContainedInEnvelope a owl:ObjectProperty ;
    rdfs:label "is contained in envelope" ;
    rdfs:comment "Inverse of containsMessage: relates a message to its containing envelope." ;
    rdfs:domain :Message ;
    rdfs:range :InterchangeEnvelope .

:hasSegment a owl:ObjectProperty ;
    rdfs:label "has segment" ;
    rdfs:comment "Relates a message to its segments." ;
    rdfs:domain :Message ;
    rdfs:range :Segment ;
    owl:inverseOf :isSegmentOf .

:isSegmentOf a owl:ObjectProperty ;
    rdfs:label "is segment of" ;
    rdfs:comment "Inverse of hasSegment: relates a segment to the message it belongs to." ;
    rdfs:domain :Segment ;
    rdfs:range :Message .

:hasCompositeElement a owl:ObjectProperty ;
    rdfs:label "has composite element" ;
    rdfs:comment "Relates a segment to its composite data elements." ;
    rdfs:domain :Segment ;
    rdfs:range :CompositeDataElement ;
    owl:inverseOf :isCompositeElementOf .

:isCompositeElementOf a owl:ObjectProperty ;
    rdfs:label "is composite element of" ;
    rdfs:comment "Inverse of hasCompositeElement: relates a composite data element to its parent segment." ;
    rdfs:domain :CompositeDataElement ;
    rdfs:range :Segment .

:hasSimpleElement a owl:ObjectProperty ;
    rdfs:label "has simple element" ;
    rdfs:comment "Relates a composite data element to its simple data elements." ;
    rdfs:domain :CompositeDataElement ;
    rdfs:range :SimpleDataElement ;
    owl:inverseOf :isSimpleElementOf .

:isSimpleElementOf a owl:ObjectProperty ;
    rdfs:label "is simple element of" ;
    rdfs:comment "Inverse of hasSimpleElement: relates a simple data element to its composite parent." ;
    rdfs:domain :SimpleDataElement ;
    rdfs:range :CompositeDataElement .

:hasHeader a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:label "has header" ;
    rdfs:comment "Relates an invoice message to its header section." ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :InvoiceHeader ;
    owl:inverseOf :isHeaderOf .

:isHeaderOf a owl:ObjectProperty ;
    rdfs:label "is header of" ;
    rdfs:comment "Inverse of hasHeader: relates an invoice header to its message." ;
    rdfs:domain :InvoiceHeader ;
    rdfs:range :InvoiceMessage .

:hasDetail a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:label "has detail" ;
    rdfs:comment "Relates an invoice message to its detail section." ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :InvoiceDetail ;
    owl:inverseOf :isDetailOf .

:isDetailOf a owl:ObjectProperty ;
    rdfs:label "is detail of" ;
    rdfs:comment "Inverse of hasDetail: relates an invoice detail section to its message." ;
    rdfs:domain :InvoiceDetail ;
    rdfs:range :InvoiceMessage .

:hasSummary a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:label "has summary" ;
    rdfs:comment "Relates an invoice message to its summary section." ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :InvoiceSummary ;
    owl:inverseOf :isSummaryOf .

:isSummaryOf a owl:ObjectProperty ;
    rdfs:label "is summary of" ;
    rdfs:comment "Inverse of hasSummary: relates an invoice summary to its message." ;
    rdfs:domain :InvoiceSummary ;
    rdfs:range :InvoiceMessage .

:involvesOrganization a owl:ObjectProperty ;
    rdfs:label "involves organization" ;
    rdfs:comment "Relates an invoice message to organizations involved." ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :Organization ;
    owl:inverseOf :isOrganizationInvolvedIn .

:isOrganizationInvolvedIn a owl:ObjectProperty ;
    rdfs:label "is organization involved in" ;
    rdfs:comment "Inverse of involvesOrganization: relates an organization to the invoice messages it is involved in." ;
    rdfs:domain :Organization ;
    rdfs:range :InvoiceMessage .

:assignedRole a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:label "assigned role" ;
    rdfs:comment "The role assigned to an organization in a specific context." ;
    rdfs:domain :OrganizationRoleAssignment ;
    rdfs:range :AgentRole ;
    owl:inverseOf :isRoleAssignment .

:isRoleAssignment a owl:ObjectProperty ;
    rdfs:label "is role assignment" ;
    rdfs:comment "Inverse of assignedRole: relates an agent role to the role assignments it is part of." ;
    rdfs:domain :AgentRole ;
    rdfs:range :OrganizationRoleAssignment .

:roleForOrganization a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:label "role for organization" ;
    rdfs:comment "The organization to which a role is assigned." ;
    rdfs:domain :OrganizationRoleAssignment ;
    rdfs:range :Organization ;
    owl:inverseOf :hasRoleAssignment .

:hasRoleAssignment a owl:ObjectProperty ;
    rdfs:label "has role assignment" ;
    rdfs:comment "Inverse of roleForOrganization: relates an organization to its role assignments." ;
    rdfs:domain :Organization ;
    rdfs:range :OrganizationRoleAssignment .

:roleInInvoice a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:label "role in invoice" ;
    rdfs:comment "The invoice message context for the organization role assignment." ;
    rdfs:domain :OrganizationRoleAssignment ;
    rdfs:range :InvoiceMessage ;
    owl:inverseOf :hasRoleAssignmentInInvoice .

:hasRoleAssignmentInInvoice a owl:ObjectProperty ;
    rdfs:label "has role assignment in invoice" ;
    rdfs:comment "Inverse of roleInInvoice: relates an invoice message to its organization role assignments." ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :OrganizationRoleAssignment .

:hasAddress a owl:ObjectProperty ;
    rdfs:label "has address" ;
    rdfs:comment "Relates an organization to its address." ;
    rdfs:domain :Organization ;
    rdfs:range :Address ;
    owl:inverseOf :isAddressOf .

:isAddressOf a owl:ObjectProperty ;
    rdfs:label "is address of" ;
    rdfs:comment "Inverse of hasAddress: relates an address to its organization." ;
    rdfs:domain :Address ;
    rdfs:range :Organization .

:hasLineItem a owl:ObjectProperty ;
    rdfs:label "has line item" ;
    rdfs:comment "Relates the invoice detail section to its line items." ;
    rdfs:domain :InvoiceDetail ;
    rdfs:range :LineItem ;
    owl:inverseOf :isLineItemOf .

:isLineItemOf a owl:ObjectProperty ;
    rdfs:label "is line item of" ;
    rdfs:comment "Inverse of hasLineItem: relates a line item to its invoice detail section." ;
    rdfs:domain :LineItem ;
    rdfs:range :InvoiceDetail .

:describesItem a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:label "describes item" ;
    rdfs:comment "Relates a line item to the item it describes." ;
    rdfs:domain :LineItem ;
    rdfs:range :Item ;
    owl:inverseOf :isDescribedByLineItem .

:isDescribedByLineItem a owl:ObjectProperty ;
    rdfs:label "is described by line item" ;
    rdfs:comment "Inverse of describesItem: relates an item to line items that describe it." ;
    rdfs:domain :Item ;
    rdfs:range :LineItem .

:hasNetPrice a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:label "has net price" ;
    rdfs:comment "Relates a line item to its net price." ;
    rdfs:domain :LineItem ;
    rdfs:range :Price ;
    owl:inverseOf :isNetPriceOf .

:isNetPriceOf a owl:ObjectProperty ;
    rdfs:label "is net price of" ;
    rdfs:comment "Inverse of hasNetPrice: relates a price to the line item it is the net price for." ;
    rdfs:domain :Price ;
    rdfs:range :LineItem .

:hasInvoiceAmount a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:label "has invoice amount" ;
    rdfs:comment "Relates the invoice summary to the invoice amount." ;
    rdfs:domain :InvoiceSummary ;
    rdfs:range :Price ;
    owl:inverseOf :isInvoiceAmountOf .

:isInvoiceAmountOf a owl:ObjectProperty ;
    rdfs:label "is invoice amount of" ;
    rdfs:comment "Inverse of hasInvoiceAmount: relates a price to the invoice summary it is the amount for." ;
    rdfs:domain :Price ;
    rdfs:range :InvoiceSummary .

:hasTax a owl:ObjectProperty ;
    rdfs:label "has tax" ;
    rdfs:comment "Relates the invoice summary to the tax details." ;
    rdfs:domain :InvoiceSummary ;
    rdfs:range :Tax ;
    owl:inverseOf :isTaxOf .

:isTaxOf a owl:ObjectProperty ;
    rdfs:label "is tax of" ;
    rdfs:comment "Inverse of hasTax: relates a tax to the invoice summary it is part of." ;
    rdfs:domain :Tax ;
    rdfs:range :InvoiceSummary .

:hasBusinessProcess a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:label "has business process" ;
    rdfs:comment "Assigns the invoice to a business process." ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :BusinessProcess ;
    owl:inverseOf :isBusinessProcessOf .

:isBusinessProcessOf a owl:ObjectProperty ;
    rdfs:label "is business process of" ;
    rdfs:comment "Inverse of hasBusinessProcess: relates a business process to the invoice messages it is associated with." ;
    rdfs:domain :BusinessProcess ;
    rdfs:range :InvoiceMessage .

#################################################################
# Data Properties
#################################################################

:hasGlobalLocationNumber a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:label "has GLN" ;
    rdfs:comment "The global location number of an organization." ;
    rdfs:domain :Organization ;
    rdfs:range xsd:string .

:hasReferenceNumber a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:label "has reference number" ;
    rdfs:comment "The reference number in the invoice header." ;
    rdfs:domain :InvoiceHeader ;
    rdfs:range xsd:string .

:hasInvoiceDate a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:label "has invoice date" ;
    rdfs:comment "The date of the invoice (string representation)." ;
    rdfs:domain :InvoiceHeader ;
    rdfs:range xsd:string .

:hasQuantity a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:label "has quantity" ;
    rdfs:comment "Quantity of the item in the line item." ;
    rdfs:domain :LineItem ;
    rdfs:range xsd:decimal .

:hasIdentifier a owl:DatatypeProperty ;
    rdfs:label "has identifier" ;
    rdfs:comment "A generic identifier for simple data elements." ;
    rdfs:domain :SimpleDataElement ;
    rdfs:range xsd:string .

#################################################################
# Connecting ReferenceNumber and GlobalLocationNumber
#################################################################

:hasReferenceNumberEntity a owl:ObjectProperty ;
    rdfs:label "has reference number entity" ;
    rdfs:comment "Connects InvoiceHeader to ReferenceNumber as an object." ;
    rdfs:domain :InvoiceHeader ;
    rdfs:range :ReferenceNumber ;
    owl:inverseOf :isReferenceNumberOf .

:isReferenceNumberOf a owl:ObjectProperty ;
    rdfs:label "is reference number of" ;
    rdfs:comment "Inverse of hasReferenceNumberEntity: relates ReferenceNumber to the InvoiceHeader." ;
    rdfs:domain :ReferenceNumber ;
    rdfs:range :InvoiceHeader .

:hasGLNEntity a owl:ObjectProperty ;
    rdfs:label "has GLN entity" ;
    rdfs:comment "Connects Organization to GlobalLocationNumber as an object." ;
    rdfs:domain :Organization ;
    rdfs:range :GlobalLocationNumber ;
    owl:inverseOf :isGLNOf .

:isGLNOf a owl:ObjectProperty ;
    rdfs:label "is GLN of" ;
    rdfs:comment "Inverse of hasGLNEntity: relates GlobalLocationNumber to Organization." ;
