#################################################################

:InvoiceMessage owl:equivalentClass [
    a owl:Class ;
    owl:intersectionOf (
        :Message
        [ a owl:Restriction ; owl:onProperty :hasHeader ; owl:allValuesFrom :InvoiceHeader ]
        [ a owl:Restriction ; owl:onProperty :hasDetail ; owl:allValuesFrom :InvoiceDetail ]
        [ a owl:Restriction ; owl:onProperty :hasSummary ; owl:allValuesFrom :InvoiceSummary ]
    )
] .

:LineItem owl:equivalentClass [
    a owl:Class ;
    owl:intersectionOf (
        :CompositeDataElement
        [ a owl:Restriction ; owl:onProperty :describesItem ; owl:allValuesFrom :Item ]
        [ a owl:Restriction ; owl:onProperty :hasNetPrice ; owl:allValuesFrom :Price ]
        [ a owl:Restriction ; owl:onProperty :hasQuantity ; owl:allValuesFrom xsd:decimal ]
    )
] .

