:edifact_invoice_story rdf:type owl:Ontology ;
  rdfs:label "EDIFACT Invoice Ontology" ;
  rdfs:comment "Ontology for representing EDIFACT invoice messages, aligned with D96A, EANCOM, EN16931-1, and P2P-O standards." .

#################################################################
# Classes
#################################################################

:InterchangeEnvelope rdf:type owl:Class ;
  rdfs:label "Interchange Envelope" ;
  rdfs:comment "The envelope containing EDIFACT messages." .

:Message rdf:type owl:Class ;
  rdfs:label "Message" ;
  rdfs:comment "An EDIFACT message, such as INVOIC." .

:Segment rdf:type owl:Class ;
  rdfs:label "Segment" ;
  rdfs:comment "A segment within an EDIFACT message (e.g., BGM, NAD)." .

:CompositeDataElement rdf:type owl:Class ;
  rdfs:label "Composite Data Element" ;
  rdfs:comment "A composite data element in a segment." .

:SimpleDataElement rdf:type owl:Class ;
  rdfs:label "Simple Data Element" ;
  rdfs:comment "A simple data element in a composite." .

:Invoice rdf:type owl:Class ;
  rdfs:label "Invoice" ;
  rdfs:comment "A business document representing an invoice." ;
  rdfs:subClassOf :Message .

:HeaderSection rdf:type owl:Class ;
  rdfs:label "Header Section" ;
  rdfs:comment "Header section of the invoice message." ;
  rdfs:subClassOf :Segment .

:DetailSection rdf:type owl:Class ;
  rdfs:label "Detail Section" ;
  rdfs:comment "Detail section listing line items." ;
  rdfs:subClassOf :Segment .

:SummarySection rdf:type owl:Class ;
  rdfs:label "Summary Section" ;
  rdfs:comment "Summary section providing invoice totals." ;
  rdfs:subClassOf :Segment .

:LineItem rdf:type owl:Class ;
  rdfs:label "Line Item" ;
  rdfs:comment "A line item in the detail section." .

:Organization rdf:type owl:Class ;
  rdfs:label "Organization" ;
  rdfs:comment "An organization involved in the invoice." .

:AgentRole rdf:type owl:Class ;
  rdfs:label "Agent Role" ;
  rdfs:comment "A role played by an organization (e.g., Buyer, Delivery Party)." .

:RoleAssignment rdf:type owl:Class ;
  rdfs:label "Role Assignment" ;
  rdfs:comment "Pivot class linking an organization, role, and invoice." .

:Address rdf:type owl:Class ;
  rdfs:label "Address" ;
  rdfs:comment "Address of an organization." ;
  rdfs:subClassOf :CompositeDataElement .

:Identifier rdf:type owl:Class ;
  rdfs:label "Identifier" ;
  rdfs:comment "An identifier for an organization." .

:GlobalLocationNumber rdf:type owl:Class ;
  rdfs:label "Global Location Number" ;
  rdfs:comment "GLN identifier for locations." ;
  rdfs:subClassOf :Identifier .

:Item rdf:type owl:Class ;
  rdfs:label "Item" ;
  rdfs:comment "An item sold in the invoice." .

:Price rdf:type owl:Class ;
  rdfs:label "Price" ;
  rdfs:comment "Price of an item." .

:Tax rdf:type owl:Class ;
  rdfs:label "Tax" ;
  rdfs:comment "Tax information in the summary." ;
  rdfs:subClassOf :CompositeDataElement .

:Amount rdf:type owl:Class ;
  rdfs:label "Amount" ;
  rdfs:comment "Monetary amount in the summary." ;
  rdfs:subClassOf :CompositeDataElement .

:ReferenceNumber rdf:type owl:Class ;
  rdfs:label "Reference Number" ;
  rdfs:comment "Reference number for the invoice." ;
  rdfs:subClassOf :CompositeDataElement .

:BusinessProcess rdf:type owl:Class ;
  rdfs:label "Business Process" ;
  rdfs:comment "The business process to which the invoice is assigned." .

#################################################################
