    rdfs:comment "Links an item line to its quantity." ;
    rdfs:domain :ItemLine ;
    rdfs:range :Quantity ;
    a owl:FunctionalProperty ;
    owl:inverseOf :isQuantityOfItemLine .
:isQuantityOfItemLine rdf:type owl:ObjectProperty ;
    rdfs:label "is quantity of item line" ;
