    rdfs:label "is EN16931 alignment of" ;
    rdfs:comment "Inverse of isAlignedWithEN16931." ;
    rdfs:domain :EN16931Alignment ;
    rdfs:range :Invoice .
:isAlignedWithP2PO rdf:type owl:ObjectProperty ;
    rdfs:label "is aligned with P2P-O" ;
    rdfs:comment "Links an invoice to P2P-O alignment." ;
    rdfs:domain :Invoice ;
    rdfs:range :P2POAlignment ;
    owl:inverseOf :isP2POAlignmentOf .
:isP2POAlignmentOf rdf:type owl:ObjectProperty ;
    rdfs:label "is P2P-O alignment of" ;
