    rdfs:domain :Invoice ;
    rdfs:range :OrganizationRoleAssignment .

:playsRole rdf:type owl:ObjectProperty ;
    rdfs:label "plays role" ;
    rdfs:comment "Links a role assignment to the agent role." ;
    rdfs:domain :OrganizationRoleAssignment ;
    rdfs:range :AgentRole .

:assignedTo rdf:type owl:ObjectProperty ;
    rdfs:label "assigned to" ;
    rdfs:comment "Links a role assignment to the organization." ;
    rdfs:domain :OrganizationRoleAssignment ;
    rdfs:range :Organization .

:hasItemLine rdf:type owl:ObjectProperty ;
    rdfs:label "has item line" ;
    rdfs:comment "Links a detail section to item lines." ;
    rdfs:domain :DetailSection ;
    rdfs:range :ItemLine .

:refersToItem rdf:type owl:ObjectProperty ;
    rdfs:label "refers to item" ;
    rdfs:comment "Links an item line to the item." ;
    rdfs:domain :ItemLine ;
    rdfs:range :Item .

:hasPrice rdf:type owl:ObjectProperty ;
    rdfs:label "has price" ;
    rdfs:comment "Links an item line to its price." ;
    rdfs:domain :ItemLine ;
    rdfs:range :Price ;
    owl:FunctionalProperty .

:hasQuantity rdf:type owl:ObjectProperty ;
    rdfs:label "has quantity" ;
    rdfs:comment "Links an item line to its quantity." ;
    rdfs:domain :ItemLine ;
    rdfs:range :Quantity ;
    owl:FunctionalProperty .

:hasTax rdf:type owl:ObjectProperty ;
    rdfs:label "has tax" ;
    rdfs:comment "Links a summary section to its tax amount." ;
    rdfs:domain :SummarySection ;
    rdfs:range :Tax ;
    owl:FunctionalProperty .

:hasReferenceNumber rdf:type owl:ObjectProperty ;
    rdfs:label "has reference number" ;
    rdfs:comment "Links a header section to a reference number." ;
    rdfs:domain :HeaderSection ;
    rdfs:range :ReferenceNumber ;
    owl:FunctionalProperty .

:hasInvoiceAmount rdf:type owl:ObjectProperty ;
    rdfs:label "has invoice amount" ;
    rdfs:comment "Links an invoice to its total price." ;
    rdfs:domain :Invoice ;
    rdfs:range :Price ;
    owl:FunctionalProperty .

:hasInvoiceNumber rdf:type owl:ObjectProperty ;
