# Data Properties
:date rdf:type owl:DatatypeProperty ;
    rdfs:label "date" ;
    rdfs:comment "Document date in header section." ;
    rdfs:domain :HeaderSection ;
    rdfs:range xsd:string ;
    a owl:FunctionalProperty .
:amount rdf:type owl:DatatypeProperty ;
    rdfs:label "amount" ;
    rdfs:comment "Monetary amount." ;
    rdfs:domain :Price ;
    rdfs:range xsd:decimal ;
    a owl:FunctionalProperty .
:quantityValue rdf:type owl:DatatypeProperty ;
    rdfs:label "quantity value" ;
    rdfs:comment "Quantity value for item lines." ;
    rdfs:domain :Quantity ;
    rdfs:range xsd:decimal ;
    a owl:FunctionalProperty .
:addressLine rdf:type owl:DatatypeProperty ;
    rdfs:label "address line" ;
    rdfs:comment "Street or address line." ;
    rdfs:domain :Address ;
    rdfs:range xsd:string .
:glnValue rdf:type owl:DatatypeProperty ;
    rdfs:label "GLN value" ;
    rdfs:comment "GLN identifier value." ;
    rdfs:domain :GlobalLocationNumber ;
    rdfs:range xsd:string ;
    a owl:FunctionalProperty .
:taxAmount rdf:type owl:DatatypeProperty ;
    rdfs:label "tax amount" ;
    rdfs:comment "Tax amount in summary section." ;
    rdfs:domain :Tax ;
    rdfs:range xsd:decimal ;
    a owl:FunctionalProperty .
:referenceValue rdf:type owl:DatatypeProperty ;
    rdfs:label "reference value" ;
    rdfs:comment "Reference number value." ;
    rdfs:domain :ReferenceNumber ;
    rdfs:range xsd:string ;
    a owl:FunctionalProperty .

# Advanced Axioms and Restrictions
:Invoice owl:equivalentClass [ rdf:type owl:Restriction ; owl:onProperty :hasInvoiceAmount ; owl:allValuesFrom :Price ] .
:ItemLine owl:equivalentClass [ rdf:type owl:Restriction ; owl:onProperty :hasPrice ; owl:allValuesFrom :Price ] .
:OrganizationRoleAssignment owl:equivalentClass [ rdf:type owl:Restriction ; owl:onProperty :playsRole ; owl:someValuesFrom :AgentRole ] .
:OrganizationRoleAssignment owl:equivalentClass [ rdf:type owl:Restriction ; owl:onProperty :assignedTo ; owl:someValuesFrom :Organization ] .
:Invoice rdfs:subClassOf [ rdf:type owl:Restriction ; owl:onProperty :hasValidationConstraint ; owl:someValuesFrom :ValidationConstraint ] .
:Invoice rdfs:subClassOf [ rdf:type owl:Restriction ; owl:onProperty :isAssignedToBusinessProcess ; owl:someValuesFrom :BusinessProcess ] .
:DetailSection rdfs:subClassOf [ rdf:type owl:Restriction ; owl:onProperty :hasItemLine ; owl:someValuesFrom :ItemLine ] .
:SummarySection rdfs:subClassOf [ rdf:type owl:Restriction ; owl:onProperty :hasTax ; owl:someValuesFrom :Tax ] .

# End of ontology

args.value:
@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .
@prefix owl: <http://www.w3.org/2002/07/owl#> .
@prefix : <http://www.example.org/ontology#> .

:EDIFACTOntology rdf:type owl:Ontology ;
    rdfs:label "EDIFACT Invoice Ontology" ;
    rdfs:comment "A deep ontology for UN/EDIFACT digital business documents, invoices, roles, itemization, and compliance." .

# Classes
:InterchangeEnvelope rdf:type owl:Class ;
    rdfs:label "Interchange Envelope" ;
    rdfs:comment "The EDIFACT envelope containing messages." .

:EDIFACTMessage rdf:type owl:Class ;
    rdfs:label "EDIFACT Message" ;
    rdfs:comment "A message contained within an Interchange Envelope." ;
    rdfs:subClassOf :InterchangeEnvelope .

:Invoice rdf:type owl:Class ;
    rdfs:label "Invoice" ;
    rdfs:comment "A global trade invoice message." ;
    rdfs:subClassOf :EDIFACTMessage .

:Segment rdf:type owl:Class ;
    rdfs:label "Segment" ;
    rdfs:comment "A segment within an EDIFACT message." .

:HeaderSection rdf:type owl:Class ;
    rdfs:label "Header Section" ;
    rdfs:comment "Header section of an invoice message." ;
    rdfs:subClassOf :Segment .

:DetailSection rdf:type owl:Class ;
    rdfs:label "Detail Section" ;
    rdfs:comment "Detail section listing line items." ;
    rdfs:subClassOf :Segment .

:SummarySection rdf:type owl:Class ;
    rdfs:label "Summary Section" ;
    rdfs:comment "Summary section with totals and taxes." ;
    rdfs:subClassOf :Segment .

:CompositeDataElement rdf:type owl:Class ;
    rdfs:label "Composite Data Element" ;
    rdfs:comment "A composite data element in a segment." .

:SimpleDataElement rdf:type owl:Class ;
    rdfs:label "Simple Data Element" ;
    rdfs:comment "A simple data element in a composite." .

:Organization rdf:type owl:Class ;
    rdfs:label "Organization" ;
    rdfs:comment "An organization involved in the invoice." .

:AgentRole rdf:type owl:Class ;
    rdfs:label "Agent Role" ;
    rdfs:comment "A specific role played by an organization (e.g., Buyer, Delivery Party)." ;
    rdfs:subClassOf :Organization .

:Address rdf:type owl:Class ;
    rdfs:label "Address" ;
    rdfs:comment "Address associated with an organization." ;
    rdfs:subClassOf :Organization .

:GlobalLocationNumber rdf:type owl:Class ;
    rdfs:label "Global Location Number" ;
    rdfs:comment "Global Location Number (GLN) identifier." .

:Item rdf:type owl:Class ;
    rdfs:label "Item" ;
    rdfs:comment "An item sold in the invoice." .

:Price rdf:type owl:Class ;
    rdfs:label "Price" ;
    rdfs:comment "Price associated with an item line or invoice." .

:Quantity rdf:type owl:Class ;
    rdfs:label "Quantity" ;
    rdfs:comment "Quantity of items in an item line." .

:Tax rdf:type owl:Class ;
    rdfs:label "Tax" ;
    rdfs:comment "Tax amount in the invoice summary." .

:ReferenceNumber rdf:type owl:Class ;
    rdfs:label "Reference Number" ;
    rdfs:comment "Reference number for the invoice or document." .

:BusinessProcess rdf:type owl:Class ;
    rdfs:label "Business Process" ;
    rdfs:comment "Business process assignment for the invoice." .

:ValidationConstraint rdf:type owl:Class ;
    rdfs:label "Validation Constraint" ;
    rdfs:comment "Constraint for automated validation (e.g., SHACL)." .

:PurchaseToPayOntologyAlignment rdf:type owl:Class ;
    rdfs:label "P2P-O Alignment" ;
    rdfs:comment "Alignment to the Purchase-to-Pay ontology." ;
    rdfs:subClassOf :EN16931Alignment .

:OrganizationRoleAssignment rdf:type owl:Class ;
    rdfs:label "Organization Role Assignment" ;
    rdfs:comment "Reified relationship assigning a role to an organization." .

:ItemLine rdf:type owl:Class ;
    rdfs:label "Item Line" ;
    rdfs:comment "Line item in the invoice detail section." .

:EN16931Alignment rdf:type owl:Class ;
    rdfs:label "EN 16931 Alignment" ;
    rdfs:comment "Alignment to the European Standard EN 16931-1." .

:P2POAlignment rdf:type owl:Class ;
    rdfs:label "P2P-O Alignment" ;
    rdfs:comment "Alignment to the Purchase-to-Pay ontology." .

# Disjointness
:HeaderSection owl:disjointWith :DetailSection .
:HeaderSection owl:disjointWith :SummarySection .
:DetailSection owl:disjointWith :SummarySection .
:Organization owl:disjointWith :Item .
:AgentRole owl:disjointWith :Address .
:Segment owl:disjointWith :CompositeDataElement .
:CompositeDataElement owl:disjointWith :SimpleDataElement .

# Properties
:containsMessage rdf:type owl:ObjectProperty ;
    rdfs:label "contains message" ;
    rdfs:comment "Links an envelope to its contained message." ;
    rdfs:domain :InterchangeEnvelope ;
    rdfs:range :EDIFACTMessage ;
    a owl:FunctionalProperty ;
    owl:inverseOf :isContainedInEnvelope .
:isContainedInEnvelope rdf:type owl:ObjectProperty ;
    rdfs:label "contained in envelope" ;
    rdfs:comment "Indicates a message is contained in an envelope." ;
    rdfs:domain :EDIFACTMessage ;
    rdfs:range :InterchangeEnvelope ;
    a owl:FunctionalProperty .
:hasSegment rdf:type owl:ObjectProperty ;
    rdfs:label "has segment" ;
    rdfs:comment "Links a message to its segments." ;
    rdfs:domain :EDIFACTMessage ;
    rdfs:range :Segment ;
    a owl:FunctionalProperty ;
    owl:inverseOf :isSegmentOf .
:isSegmentOf rdf:type owl:ObjectProperty ;
    rdfs:label "segment of message" ;
    rdfs:comment "Indicates a segment belongs to a message." ;
    rdfs:domain :Segment ;
    rdfs:range :EDIFACTMessage ;
    a owl:FunctionalProperty .
:hasHeader rdf:type owl:ObjectProperty ;
    rdfs:label "has header" ;
    rdfs:comment "Links a message to its header section." ;
