    rdfs:label "Simple Data Element" ;
    rdfs:comment "A simple data element in a composite." .

:Organization rdf:type owl:Class ;
    rdfs:label "Organization" ;
    rdfs:comment "An organization involved in the invoice." .

:AgentRole rdf:type owl:Class ;
    rdfs:label "Agent Role" ;
    rdfs:comment "A specific role played by an organization (e.g., Buyer, Delivery Party)." ;
    rdfs:subClassOf :Organization .

:Address rdf:type owl:Class ;
    rdfs:label "Address" ;
    rdfs:comment "Address associated with an organization." ;
    rdfs:subClassOf :Organization .

:GlobalLocationNumber rdf:type owl:Class ;
    rdfs:label "Global Location Number" ;
    rdfs:comment "Global Location Number (GLN) identifier." .

:Item rdf:type owl:Class ;
    rdfs:label "Item" ;
    rdfs:comment "An item sold in the invoice." .

:Price rdf:type owl:Class ;
    rdfs:label "Price" ;
